import { isMediaHostUrl } from '@/api/profiles/profile-picture-url';
import {
  DEFAULT_MEDIA_RESOLVER_ORIGIN,
  USER_CONTENT_MEDIA_RESOLVER_ORIGIN
} from '@/decentralized-media/decentralized-media';

// IPFS gateway URLs generated by the app for pinned media, on the 6529.io
// path gateway or the separate content domain's path gateway.
const IPFS_GATEWAY_ORIGINS: readonly string[] = [
  DEFAULT_MEDIA_RESOLVER_ORIGIN,
  USER_CONTENT_MEDIA_RESOLVER_ORIGIN
];

function isIpfsGatewayUrlOn(value: string, origin: string): boolean {
  const prefix = `${origin}/ipfs/`;
  if (
    !value.startsWith(prefix) ||
    value.length === prefix.length ||
    /\s/.test(value)
  ) {
    return false;
  }
  try {
    const url = new URL(value);
    return (
      url.origin === origin &&
      url.port === '' &&
      url.username === '' &&
      url.password === '' &&
      url.pathname.startsWith('/ipfs/')
    );
  } catch {
    return false;
  }
}

function isIpfsGatewayUrl(value: string): boolean {
  return IPFS_GATEWAY_ORIGINS.some((origin) =>
    isIpfsGatewayUrlOn(value, origin)
  );
}

/**
 * Push notification images are fetched by the receiving device, so only
 * images served from our own media hosts are attached: the media CDN (same
 * exact check as new profile pictures) or an IPFS path gateway under /ipfs/.
 */
export function isAllowedPushNotificationImageUrl(
  url: string | null | undefined
): url is string {
  if (typeof url !== 'string') {
    return false;
  }
  const value = url.trim();
  return value !== '' && (isMediaHostUrl(value) || isIpfsGatewayUrl(value));
}
